function syncCredentialActionRow(row){const type=row.querySelector('[name="extra_action_type"]').value,element=row.querySelector('[name="extra_element_id"]'),value=row.querySelector('[name="extra_value"]');element.disabled=type==="wait";element.required=type!=="wait";value.disabled=!["type","key","wait"].includes(type);value.placeholder=type==="wait"?"Seconds":type==="key"?"For example, ENTER":"Text";if(value.disabled)value.value=""}
function addCredentialActionRow(action={}){const row=document.createElement("div");row.className="credential-extra-row";row.dataset.credentialAction="1";row.innerHTML=`<label>Action<select name="extra_action_type">${credentialActionTypeOptions(action.action_type||"click")}</select></label><label>Object<select name="extra_element_id">${credentialElementOptions(action.element_id||"")}</select></label><label>Value<input name="extra_value" value="${esc(action.value??action.seconds??"")}"></label><button type="button" class="item-delete" title="Remove step" aria-label="Remove step">×</button>`;$("#credentialExtraActions").append(row);row.querySelector('[name="extra_action_type"]').onchange=()=>syncCredentialActionRow(row);row.querySelector(".item-delete").onclick=()=>row.remove();syncCredentialActionRow(row)}
