function readCredentialExtraActions(){return $$('[data-credential-action]').map(row=>{const type=row.querySelector('[name="extra_action_type"]').value,item={action_type:type};if(type==="wait")item.seconds=Number(row.querySelector('[name="extra_value"]').value||1);else{item.element_id=Number(row.querySelector('[name="extra_element_id"]').value);if(["type","key"].includes(type))item.value=row.querySelector('[name="extra_value"]').value||""}return item}).filter(item=>item.action_type==="wait"||item.element_id)}
