const parameterOptionLabels={text:"Text",value:"Value",index:"Index",present:"Present",visible:"Visible",clickable:"Clickable",hidden:"Hidden",click:"Click",double_click:"Double click",context_click:"Right click",hover:"Hover",type:"Type text",key:"Press key"};
const parameterOptionLabel=value=>t(parameterOptionLabels[value]||value);
const elementActions=new Set(["click","double_click","context_click","hover","focus","type","clear","submit","select","key","scroll_to","drag_to","wait_for","upload","screenshot","switch_frame","repeat_click","repeat_until"]);
const parameterConfig={auto_login:[["credential_id","Login profile","credentials"]],repeat_click:[["clicks_per_second","Clicks per second","number",1],["duration_seconds","Duration in seconds (0 = infinite)","number",0]],repeat_until:[["target_element_id","Object 2 to wait for","elements"],["operation","Action on Object 1","select:click|double_click|context_click|hover|type|key"],["value","Text or key for the action","text"],["interval_seconds","Repeat interval in seconds","number",0.5],["timeout_seconds","Timeout in seconds (0 = infinite)","number",0]],type:[["text","Text","text"],["clear","Clear first","checkbox"]],select:[["by","Select by","select:text|value|index"],["value","Value","text"]],key:[["key","Key (for example, ENTER)","text"]],scroll_by:[["x","Move X","number"],["y","Move Y","number"]],mouse_move:[["x","X pixels","number"],["y","Y pixels","number"]],drag_to:[["target_element_id","Target object","elements"]],wait:[["seconds","Seconds","number"]],wait_random:[["min","Minimum seconds","number"],["max","Maximum seconds","number"]],wait_for:[["condition","Condition","select:present|visible|clickable|hidden"],["timeout","Timeout seconds","number"]],navigate:[["url","URL address","text"]],switch_window:[["index","Window index (-1 last)","number"]],upload:[["path","Absolute file path","text"]],screenshot:[["filename","File name","text"]],script:[["script","JavaScript","textarea"]],cookie_set:[["name","Cookie name","text"],["value","Value","text"]]};
function renderParameterFields(){const type=$("#actionType").value,needsElement=elementActions.has(type);$("#actionElementWrap").style.display=needsElement?"block":"none";$("#actionElement").required=needsElement;const fields=parameterConfig[type]||[];$("#parameterFields").innerHTML=fields.map(([name,label,kind,initial])=>{if(kind==="checkbox")return `<label><input type="checkbox" name="${name}" style="display:inline;width:auto"> ${label}</label>`;if(kind==="textarea")return `<label>${label}<textarea name="${name}" rows="4"></textarea></label>`;if(kind==="elements")return `<label>${label}<select name="${name}" required>${state.elements.map(e=>`<option value="${e.id}">${esc(e.name)}</option>`).join("")}</select></label>`;if(kind==="credentials")return `<label>${label}<select name="${name}" required>${state.credentials.map(e=>`<option value="${e.id}">${esc(e.name)}</option>`).join("")}</select></label>`;if(kind.startsWith("select:"))return `<label>${label}<select name="${name}">${kind.slice(7).split("|").map(x=>`<option value="${x}">${parameterOptionLabel(x)}</option>`).join("")}</select></label>`;return `<label>${label}<input type="${kind}" name="${name}" value="${initial??""}" ${kind==="number"?'step="any"':""}></label>`}).join("")}
function actionInsertPosition(){return state.selectedActions.size?Math.max(...state.selectedActions)+1:state.actions.length}
function fillActionForm(action){const form=$("#actionForm");form.elements.action_type.value=action.action_type;renderParameterFields();if(form.elements.element_id)form.elements.element_id.value=action.element_id||"";for(const [name,value] of Object.entries(action.parameters||{})){const field=form.elements[name];if(!field)continue;if(field.type==="checkbox")field.checked=!!value;else field.value=value??""}}
function openActionDialog(index=null){if(!state.selectedWorkflow)return toast("Create or select a workflow first",true);state.editingActionIndex=index;const form=$("#actionForm");form.reset();if(index===null){state.insertAt=actionInsertPosition();$("#actionDialogEyebrow").textContent="NEW STEP";$("#actionDialogTitle").textContent="Add action";$("#actionSubmitButton").textContent="Add to list";renderParameterFields();updateInsertMarker()}else{const action=state.actions[index];if(!action)return;$("#actionDialogEyebrow").textContent="EDIT STEP";$("#actionDialogTitle").textContent=`Edit action ${index+1}`;$("#actionSubmitButton").textContent="Save changes";fillActionForm(action)}$("#actionDialog").showModal()}
function openSimple(mode){const isSite=mode==="site";$("#simpleForm").dataset.mode=mode;$("#simpleTitle").textContent=isSite?"Save site":"Create workflow";$("#simpleEyebrow").textContent=isSite?"LIBRARY":"AUTOMATION";$("#simpleFields").innerHTML=isSite?`<label>Site name<input name="name" required value="${esc(state.browser.title||"")}"></label><label>URL<input name="url" required value="${esc(state.browser.url||$("#urlInput").value)}"></label>`:`<label>Workflow name<input name="name" required placeholder="For example, login and export"></label><label>For site<select name="site_id"><option value="">No site</option>${state.sites.map(x=>`<option value="${x.id}">${esc(x.name)}</option>`).join("")}</select></label><label>Description<textarea name="description"></textarea></label>`;$("#simpleDialog").showModal()}

