$("#exportElements").onclick=()=>{const link=document.createElement("a");link.href="/api/elements/export";document.body.append(link);link.click();link.remove();$("#exportElements").closest("details").removeAttribute("open");toast("Object export was created")};
$("#importElements").onclick=()=>{$("#importElements").closest("details").removeAttribute("open");$("#elementImportFile").click()};
$("#elementImportFile").onchange=e=>guard(async()=>{const file=e.target.files[0];if(!file)return;if(file.size>100*1024*1024)throw new Error("Object backup file is too large");try{const archive=JSON.parse(await file.text());const result=await post("/api/elements/import",archive);await bootstrap();toast(`Objects imported: ${result.created}, already existed: ${result.reused}`)}finally{e.target.value=""}});
$("#exportCredentials").onclick=()=>{if(!confirm("Login profile export contains readable username and password. Store the file securely. Continue?"))return;const link=document.createElement("a");link.href="/api/credentials/export";document.body.append(link);link.click();link.remove();$("#credentialTools").removeAttribute("open");toast("Login profile export was created")};
$("#importCredentials").onclick=()=>{$("#credentialTools").removeAttribute("open");$("#credentialImportFile").click()};
$("#credentialImportFile").onchange=e=>guard(async()=>{const file=e.target.files[0];if(!file)return;if(file.size>5*1024*1024)throw new Error("Login profile backup file is too large");try{const archive=JSON.parse(await file.text());if(!confirm("Import will overwrite profiles with the same name and re-encrypt saved values for this Windows account. Continue?"))return;const result=await post("/api/credentials/import",archive);await bootstrap();toast(`Profile import: new ${result.created}, updated ${result.updated}`)}finally{e.target.value=""}});
$("#elementForm").onsubmit=async e=>{e.preventDefault();const form=new FormData(e.target),p=Object.fromEntries(form);p.site_id=p.site_id?+p.site_id:null;p.parent_id=p.parent_id?+p.parent_id:null;if(state.editingElementId){await guard(()=>api(`/api/elements/${state.editingElementId}`,{method:"PUT",body:JSON.stringify(p)}));toast("Object changes saved")}else{p.alternatives=state.selection.alternatives;p.metadata={tag:state.selection.tag,text:state.selection.text,linkText:state.selection.linkText,optionValue:state.selection.optionValue,rect:state.selection.rect};await guard(()=>post("/api/elements",p));toast("Object saved")}state.editingElementId=null;$("#elementDialog").close();await bootstrap()};
$("#actionForm").onsubmit=async e=>{e.preventDefault();const form=new FormData(e.target),raw=Object.fromEntries(form),type=raw.action_type,parameters={};(parameterConfig[type]||[]).forEach(([name,,kind])=>{let value=kind==="checkbox"?form.has(name):raw[name];if(kind==="number")value=Number(value);if(kind==="elements"||kind==="credentials")value=Number(value);parameters[name]=value});const action={action_type:type,element_id:elementActions.has(type)&&raw.element_id?+raw.element_id:null,parameters,enabled:true};if(state.editingActionIndex!==null){const index=state.editingActionIndex;if(state.actions[index])action.enabled=state.actions[index].enabled!==false;state.actions[index]=action;state.selectedActions=new Set([index]);state.selectionAnchor=index;state.insertAt=index+1;toast("Action updated")}else{const at=Math.max(0,Math.min(state.actions.length,state.insertAt));state.actions.splice(at,0,action);state.selectedActions=new Set([at]);state.selectionAnchor=at;state.insertAt=at+1;toast("Action added")}state.editingActionIndex=null;await saveActions();$("#actionDialog").close()};
$("#credentialForm").onsubmit=async e=>{e.preventDefault();const p=Object.fromEntries(new FormData(e.target));for(const key of ["site_id","username_element_id","password_element_id","submit_element_id"])p[key]=p[key]?Number(p[key]):null;p.extra_actions=readCredentialExtraActions();if(state.editingCredentialId){await guard(()=>api(`/api/credentials/${state.editingCredentialId}`,{method:"PUT",body:JSON.stringify(p)}));toast("Login profile updated")}else{await guard(()=>post("/api/credentials",p));toast("Login profile saved securely")}state.editingCredentialId=null;$("#credentialDialog").close();e.target.reset();renderCredentialExtraActions([]);await bootstrap()};
$("#simpleForm").onsubmit=async e=>{e.preventDefault();const mode=e.target.dataset.mode,p=Object.fromEntries(new FormData(e.target));if(p.site_id)p.site_id=+p.site_id;const item=await guard(()=>post(`/api/${mode==="site"?"sites":"workflows"}`,p));$("#simpleDialog").close();await bootstrap();if(mode==="workflow")await loadWorkflow(item.id);toast(mode==="site"?"Site saved":"Workflow created")};
$("#loopEnabled").onchange=e=>{$("#loopCount").hidden=!e.target.checked};
$("#playButton").onclick=()=>guard(async()=>{if(state.runner.status==="paused")return renderRunner(await post("/api/runner/resume"));if(!state.selectedWorkflow)return toast("Select workflow",true);const repeat_count=$("#loopEnabled").checked?Number($("#loopCount").value):1;renderRunner(await post(`/api/runner/start/${state.selectedWorkflow}`,{repeat_count}))});$("#pauseButton").onclick=()=>guard(async()=>renderRunner(await post("/api/runner/pause")));$("#stopButton").onclick=()=>guard(async()=>renderRunner(await post("/api/runner/stop")));
document.addEventListener("pointerup",()=>state.selectionDrag=null);
document.addEventListener("pointercancel",()=>state.selectionDrag=null);
window.addEventListener("blur",()=>state.selectionDrag=null);
document.addEventListener("pointerdown",event=>{if(!$("#actionContextMenu").contains(event.target))hideActionContextMenu()});
document.addEventListener("keydown",event=>{const editing=event.target.closest?.("input,textarea,select,[contenteditable='true']");if(editing)return;const key=event.key.toLowerCase();if((event.ctrlKey||event.metaKey)&&key==="c"&&state.selectedActions.size){event.preventDefault();copySelectedActions()}else if((event.ctrlKey||event.metaKey)&&key==="v"&&state.selectedWorkflow&&state.actionClipboard.length){event.preventDefault();guard(()=>pasteActionsAt())}else if(!event.ctrlKey&&!event.metaKey&&/^[0-9]$/.test(event.key)&&state.selectedActions.size===1){event.preventDefault();state.moveBuffer=(state.moveBuffer+event.key).slice(0,4);$("#insertPositionLabel").textContent=`Move to position ${Number(state.moveBuffer)} confirm with Enter`}else if(event.key==="Enter"&&state.moveBuffer){event.preventDefault();guard(()=>moveSelectedActionToPosition(Number(state.moveBuffer)))}else if(event.key==="Escape"){state.moveBuffer="";hideActionContextMenu();updateInsertMarker()}});
let runnerPollRunning=false,browserPollRunning=false;
setInterval(async()=>{if(runnerPollRunning)return;runnerPollRunning=true;try{renderRunner(await api("/api/runner/status"))}catch(e){}finally{runnerPollRunning=false}},250);
setInterval(async()=>{if(browserPollRunning)return;browserPollRunning=true;try{state.browser=await api("/api/browser/status");renderBrowser()}catch(e){}finally{browserPollRunning=false}},1200);
bootstrap().catch(e=>toast(e.message,true));
